-- PR 017: navigasi utama dikelompokkan (Beranda, Dasbor, Transaksi, Integrasi, Bantuan & Dokumentasi).
-- Item "Form PE" bertanda source=pe_forms: sub-menu per penyakit dibangkitkan frontend dari registri
-- pe_form_definitions (/api/v1/pe/forms), sehingga formulir baru muncul otomatis; "Daftar PE" (/pe) tetap statis.
-- Grup MASTER DATA (Data Provinsi, Data Kabupaten/Kota, Data Penyakit) dikeluarkan dari menu; rutenya tetap ada.
-- Rollback: rollback/028_rollback.sql
BEGIN;
CREATE TABLE IF NOT EXISTS app_settings_bak_028 AS SELECT key, value FROM app_settings WHERE key = 'navigation_menu';
UPDATE app_settings SET value = $nav$[{"id": "grp_beranda", "title": "Beranda", "order": 1, "enabled": true, "items": [{"id": "mod_beranda", "label": "Beranda", "href": "/", "icon": "Home", "description": "Ringkasan situasi dan rilis data surveilans terkini", "order": 1, "enabled": true}]}, {"id": "grp_dasbor", "title": "Dasbor", "order": 2, "enabled": true, "items": [{"id": "mod_main_dashboard", "label": "Dasbor Utama", "href": "/main-dashboard", "icon": "LayoutDashboard", "description": "Indikator SKDR, peta sebaran, dan Kinerja 7-1-7", "order": 1, "enabled": true}, {"id": "mod_penyakit", "label": "Penyakit", "href": "/penyakit", "icon": "Stethoscope", "description": "Profil, tren, dan sebaran kasus per penyakit", "order": 2, "enabled": true}, {"id": "mod_tv", "label": "Mode TV", "href": "/tv", "icon": "Tv", "description": "Tampilan layar lebar ruang pemantauan (sedang dalam pengembangan)", "order": 3, "enabled": true}]}, {"id": "grp_transaksi", "title": "Transaksi", "order": 3, "enabled": true, "items": [{"id": "mod_form_pe", "label": "Form PE", "href": "#", "icon": "FileText", "description": "Formulir Penyelidikan Epidemiologi per penyakit", "source": "pe_forms", "order": 1, "enabled": true, "subItems": [{"id": "sub_pe_daftar", "label": "Daftar PE", "href": "/pe", "icon": "FileSpreadsheet", "description": "Seluruh laporan PE lintas penyakit", "order": 99, "enabled": true}]}]}, {"id": "grp_integrasi", "title": "Integrasi", "order": 4, "enabled": true, "items": [{"id": "mod_ebs_sync", "label": "Sinkronisasi EBS", "href": "/ebs", "icon": "Radio", "description": "Penarikan dan pemantauan data sinyal EBS", "order": 1, "enabled": true}]}, {"id": "grp_bantuan", "title": "Bantuan & Dokumentasi", "order": 5, "enabled": true, "items": [{"id": "mod_dokumentasi", "label": "Dokumentasi", "href": "/dokumentasi", "icon": "BookText", "description": "Panduan penggunaan, definisi indikator, dan sumber data", "order": 1, "enabled": true}]}]$nav$, updated_at = now() WHERE key = 'navigation_menu';
COMMIT;
